```json
{"version":1,"taskId":"322e983d-bbe5-4693-b8c1-2d62f9d1aeb4","commandId":"rot-obst-b1","operation":"run","headSha":"9bf2556a277fa1aeb05caec89a277aa6c729492f","timeoutSeconds":300,"command":"set -e
cat > src/obstacles/RapierObstaclePhysics.ts <<'EOF'
import RAPIER from '@dimforge/rapier3d-compat';
import type { Quat } from '../contracts/math';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import { IDENTITY_QUATERNION } from './types';
import type { ObstacleBodyHandle, ObstacleBodySpec, ObstaclePhysicsAdapter } from './types';

export const OBSTACLE_COLLISION_GROUPS = collisionGroups(
  CollisionLayers.OBSTACLE,
  CollisionLayers.BALL,
);

export interface RapierObstaclePhysicsOptions {
  friction?: number;
  restitution?: number;
  collisionGroups?: number;
}

export class RapierObstaclePhysics implements ObstaclePhysicsAdapter {
  private readonly defaultFriction: number;
  private readonly defaultRestitution: number;
  private readonly groups: number;

  constructor(private readonly physics: PhysicsWorld, options: RapierObstaclePhysicsOptions = {}) {
    this.defaultFriction = options.friction ?? 0.4;
    this.defaultRestitution = options.restitution ?? 0.65;
    this.groups = options.collisionGroups ?? OBSTACLE_COLLISION_GROUPS;
  }

  createBody(spec: ObstacleBodySpec): ObstacleBodyHandle {
    const world = this.physics.world;
    const kinematic = spec.kind === 'kinematic';
    const desc = (kinematic ? RAPIER.RigidBodyDesc.kinematicPositionBased() : RAPIER.RigidBodyDesc.fixed())
      .setTranslation(spec.position.x, spec.position.y, spec.position.z)
      .setRotation(spec.rotation);
    const body = world.createRigidBody(desc);

    for (const collider of spec.colliders) {
      world.createCollider(
        RAPIER.ColliderDesc.cuboid(collider.halfExtents.x, collider.halfExtents.y, collider.halfExtents.z)
          .setTranslation(collider.offset.x, collider.offset.y, collider.offset.z)
          .setRotation(collider.rotation ?? IDENTITY_QUATERNION)
          .setFriction(collider.friction ?? this.defaultFriction)
          .setRestitution(collider.restitution ?? this.defaultRestitution)
          .setCollisionGroups(this.groups),
        body,
      );
    }

    let removed = false;
    return {
      setNextRotation(rotation: Quat): void {
        if (removed) return;
        if (kinematic) body.setNextKinematicRotation(rotation);
        else body.setRotation(rotation, true);
      },
      dispose(): void {
        if (removed) return;
        removed = true;
        world.removeRigidBody(body);
      },
    };
  }
}
EOF
wc -l src/obstacles/RapierObstaclePhysics.ts"}
